<file path="src/credits.js">
import { invoiceTotals } from './invoices.js';
import { isValidDate } from './dates.js';
import { ok, fail } from './result.js';

/**
 * Calculate the next credit note number for a given date.
 * Format: CN-<year>-<counter> where counter is 4 digits, restarting each year.
 * @param {Array<string>} existingNumbers
 * @param {string} issueDate
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
function nextCreditNoteNumber(existingNumbers, issueDate) {
  // Validate date format and reality
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  const year = parseInt(issueDate.split('-')[0], 10);

  // Find all credit note numbers for this year
  const pattern = new RegExp(`^CN-${year}-(\\d{4})$`);
  const yearCounters = (existingNumbers || [])
    .filter((num) => pattern.test(num))
    .map((num) => {
      const match = pattern.exec(num);
      return parseInt(match[1], 10);
    });

  // Find the next counter
  const maxCounter = yearCounters.length === 0 ? 0 : Math.max(...yearCounters);
  const nextCounter = maxCounter + 1;

  // Validate counter doesn't exceed 9999
  if (nextCounter > 9999) return fail('TOO_MANY_INVOICES');

  const number = `CN-${year}-${String(nextCounter).padStart(4, '0')}`;
  return ok(number);
}

/**
 * Create a credit note for an issued invoice.
 * @param {object} invoice
 * @param {{ amount: number, reason: string, date: string }}
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function createCreditNote(invoice, { amount, reason, date }, existingNumbers) {
  // Validate invoice is issued, partially_paid, or paid
  if (!invoice || !['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
    return fail('NOT_ISSUED');
  }

  // Validate amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  // Validate date format
  if (!isValidDate(date)) {
    return fail('DATE_INVALID');
  }

  // Get invoice total to validate credit amount
  const totals = invoiceTotals(invoice);
  if (!totals.ok) return totals;

  // Validate credit amount doesn't exceed invoice total
  if (amount > totals.value.total) {
    return fail('CREDIT_TOO_HIGH');
  }

  // Get next credit note number
  const numberResult = nextCreditNoteNumber(existingNumbers, date);
  if (!numberResult.ok) return numberResult;

  const creditNote = {
    number: numberResult.value,
    invoiceNumber: invoice.number,
    customerId: invoice.customerId,
    amount,
    reason,
    date,
  };

  return ok(creditNote);
}
</file>

<file path="src/customers.js">
import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const CUSTOMERS = JSON.parse(readFileSync(new URL('../data/customers.json', import.meta.url), 'utf8'));

/**
 * Discount percentages by customer tier.
 */
export const TIER_DISCOUNTS = {
  gold: 5,
  silver: 2.5,
  standard: 0,
};

/**
 * Normalize a customer ID: trim whitespace and convert to uppercase.
 * @param {string} id
 * @returns {string}
 */
export function normalizeId(id) {
  return String(id).trim().toUpperCase();
}

/**
 * All customers: { id, name, email, country, tier }.
 */
export function listCustomers() {
  return CUSTOMERS.map((c) => ({ ...c }));
}

/**
 * One customer by id.
 * @param {string} id
 */
export function getCustomer(id) {
  const normalizedId = normalizeId(id);
  const c = CUSTOMERS.find((x) => x.id === normalizedId);
  return c ? ok({ ...c }) : fail('CUSTOMER_NOT_FOUND');
}

/**
 * Check a customer record before it is stored.
 * @param {{ id?: string, name?: string, email?: string }} c
 */
export function validateCustomer(c) {
  if (!c || !c.id || !c.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email ?? '')) return fail('CUSTOMER_INVALID');
  return ok({ ...c });
}
</file>

<file path="src/dates.js">
/**
 * Check if a text is a valid date in YYYY-MM-DD format.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text ?? '')) return false;
  const [year, month, day] = text.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() + 1 === month && date.getUTCDate() === day;
}

/**
 * Add n days to a date (YYYY-MM-DD string), all in UTC.
 * @param {string} date
 * @param {number} n
 * @returns {string}
 */
export function addDays(date, n) {
  const [year, month, day] = date.split('-').map(Number);
  const d = new Date(Date.UTC(year, month - 1, day));
  d.setUTCDate(d.getUTCDate() + n);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dy = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${dy}`;
}

/**
 * Calculate days between two dates (b minus a), in whole days, all in UTC.
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
export function daysBetween(a, b) {
  const [ay, am, ad] = a.split('-').map(Number);
  const [by, bm, bd] = b.split('-').map(Number);
  const dateA = new Date(Date.UTC(ay, am - 1, ad));
  const dateB = new Date(Date.UTC(by, bm - 1, bd));
  const diffMs = dateB - dateA;
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

/**
 * Calculate the due date for an invoice based on terms.
 * @param {string} issueDate (YYYY-MM-DD format)
 * @param {string} terms ('NET14', 'NET30', or 'EOM')
 * @returns {string} due date (YYYY-MM-DD format)
 */
export function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') return addDays(issueDate, 14);
  if (terms === 'NET30') return addDays(issueDate, 30);
  if (terms === 'EOM') {
    const [year, month] = issueDate.split('-').map(Number);
    const nextMonth = month === 12 ? 1 : month + 1;
    const nextYear = month === 12 ? year + 1 : year;
    const firstDayOfNextMonth = `${nextYear}-${String(nextMonth).padStart(2, '0')}-01`;
    return addDays(firstDayOfNextMonth, -1);
  }
  return null;
}
</file>

